window.docContents[227].resolve({"/5___-Representations-of-finite-groups___-Further-results/5___18___-Schur-Weyl-duality-for-______mathfrak___gl____LPAR_V_RPAR____/Schur-Weyl-duality___-V_________n___-___-___-V_lambda-___-L_lambda/#Chapter5___Theorem5___18___4":{"contents":"Theorem 5.18.4. (i) The image A of k[S_n] and the image B of \\mathcal{U}(\\mathfrak{gl}(V)) in \\operatorname{End}(V^{\\otimes n}) are centralizers of each other.\n\n(ii) Both A and B are semisimple. In particular, V^{\\otimes n} is a semisimple \\mathfrak{gl}(V)-module.\n\n(iii) We have a decomposition of (A \\otimes B)-modules\n\nV^{\\otimes n} = \\bigoplus_{\\lambda} V_{\\lambda} \\otimes L_{\\lambda},\n\nwhere the summation is taken over partitions of n, V_{\\lambda} are Specht modules for S_n, and L_{\\lambda} are some distinct irreducible representations of \\mathfrak{gl}(V) or zero.\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.18. Schur-Weyl duality for $\\mathfrak{gl}(V)$\tSchur-Weyl duality: V^{⊗n} = ⊕ V_lambda ⊗ L_lambda","header":"Schur-Weyl duality: V^{⊗n} = ⊕ V_lambda ⊗ L_lambda","id":"/5___-Representations-of-finite-groups___-Further-results/5___18___-Schur-Weyl-duality-for-______mathfrak___gl____LPAR_V_RPAR____/Schur-Weyl-duality___-V_________n___-___-___-V_lambda-___-L_lambda/#Chapter5___Theorem5___18___4"}});
